-- Replaces the 918 wger exercises with the 1,324 exercises in backend/app/data/exercises_catalog.json.
--
-- DESTRUCTIVE: workout_sets and routine_exercises reference exercises with ON DELETE CASCADE, so
-- this deletes every logged set and every routine exercise. Take a backup first. It cannot be undone.
-- Run it together with the deploy of this code: code still using the old catalog cannot save workouts.
--
-- It runs as one transaction: any error leaves the database exactly as it was.

BEGIN;

-- Today's and future plans hold old exercise IDs and could not be saved. The planner builds new ones.
DELETE FROM public.workout_plans WHERE plan_date >= current_date;

DELETE FROM public.exercises;


DO $$
BEGIN
  IF (SELECT count(*) FROM public.exercises) <> 1324 THEN
    RAISE EXCEPTION 'Expected 1324 exercises';
  END IF;
END $$;

COMMIT;

-- Left in place on purpose: workouts and routines that have just lost all their exercises. They show
-- as empty entries. To remove them too, run these after the transaction above:
--   DELETE FROM public.workouts w WHERE NOT EXISTS (SELECT 1 FROM public.workout_sets s WHERE s.workout_id = w.id);
--   DELETE FROM public.routines r WHERE NOT EXISTS (SELECT 1 FROM public.routine_exercises e WHERE e.routine_id = r.id);
